<?php $page = max(1, (int) ($pagination['page'] ?? 1));
$pages = max(1, (int) ($pagination['pages'] ?? 1));
$page = min($page, $pages);
$start = max(1, $page - 2);
$end = min($pages, $page + 2);
$base = array_filter($filters ?? [], static fn ($value) => $value !== '' && $value !== null && $value !== 0); ?>
<nav class="ri-pagination pharmacy-review-pagination" aria-label="Prescription review pagination"><form method="get" action="<?= current_url() ?>" class="form-inline"><input type="hidden" name="view" value="<?= esc($view ?? 'list') ?>"><input type="hidden" name="search" value="<?= esc($filters['search'] ?? '') ?>"><input type="hidden" name="status" value="<?= esc($filters['status'] ?? '') ?>"><input type="hidden" name="review_state" value="<?= esc($filters['review_state'] ?? '') ?>"><input type="hidden" name="doctor_id" value="<?= (int) ($filters['doctor_id'] ?? 0) ?>"><input type="hidden" name="from" value="<?= esc($filters['from'] ?? '') ?>"><input type="hidden" name="to" value="<?= esc($filters['to'] ?? '') ?>"><label class="small text-muted mr-2" for="review-page-size">Rows</label><select class="custom-select custom-select-sm" id="review-page-size" name="page_size" onchange="this.form.submit()"><?php foreach ([10, 15, 25, 50] as $size): ?><option value="<?= $size ?>" <?= (int) ($pagination['page_size'] ?? 15) === $size ? 'selected' : '' ?>><?= $size ?></option><?php endforeach; ?></select></form><span class="ri-pagination-summary">Page <?= $page ?> of <?= $pages ?> (<?= (int) ($pagination['total'] ?? 0) ?> total)</span><div class="ri-pagination-controls"><a class="ri-page-link <?= $page <= 1 ? 'is-disabled' : '' ?>" href="<?= $page > 1 ? base_url('pharmacy/prescriptions?' . http_build_query(array_merge($base, ['view' => $view, 'page' => $page - 1]))) : '#' ?>" aria-label="Previous page" <?= $page <= 1 ? 'aria-disabled="true" tabindex="-1"' : '' ?>><i class="bi bi-chevron-left" aria-hidden="true"></i><span class="sr-only">Previous</span></a><?php if ($start > 1): ?><a class="ri-page-link" href="<?= base_url('pharmacy/prescriptions?' . http_build_query(array_merge($base, ['view' => $view, 'page' => 1]))) ?>">1</a><?php if ($start > 2): ?><span class="ri-page-ellipsis" aria-hidden="true">…</span><?php endif; ?><?php endif; ?><?php for ($number = $start; $number <= $end; $number++): ?><a class="ri-page-link <?= $number === $page ? 'is-active' : '' ?>" href="<?= base_url('pharmacy/prescriptions?' . http_build_query(array_merge($base, ['view' => $view, 'page' => $number]))) ?>" <?= $number === $page ? 'aria-current="page"' : '' ?>><?= $number ?></a><?php endfor; ?><?php if ($end < $pages): ?><?php if ($end < $pages - 1): ?><span class="ri-page-ellipsis" aria-hidden="true">…</span><?php endif; ?><a class="ri-page-link" href="<?= base_url('pharmacy/prescriptions?' . http_build_query(array_merge($base, ['view' => $view, 'page' => $pages]))) ?>"><?= $pages ?></a><?php endif; ?><a class="ri-page-link <?= $page >= $pages ? 'is-disabled' : '' ?>" href="<?= $page < $pages ? base_url('pharmacy/prescriptions?' . http_build_query(array_merge($base, ['view' => $view, 'page' => $page + 1]))) : '#' ?>" aria-label="Next page" <?= $page >= $pages ? 'aria-disabled="true" tabindex="-1"' : '' ?>><i class="bi bi-chevron-right" aria-hidden="true"></i><span class="sr-only">Next</span></a></div></nav>
